ANNOTATIONS = [
    (5, 'after', r'''PowerShell 权限检查主流程，从 bashPermissions.ts 移植并按 cmdlet 大小写不敏感重写。'''),
    (84, 'after', r'''能把文件放到调用方指定路径的 cmdlet 名单——git 内部路径守卫检查参数里有没有 hooks/、refs/、objects/、HEAD。非创建型写手（remove-item、clear-content）故意缺席：它们种不出新 hook。'''),
    (112, 'after', r'''归档解压程序：tar -xf payload.tar; git status 打的正是 isCurrentDirectoryBareGitRepo 的 TOCTOU——检查在权限评估时跑，tar 在检查之后、git 之前解出 HEAD/hooks/refs/。归档内容不透明，只能按名字一律 ask。'''),
    (126, 'after', r'''extractCommandName 用解析器取第一个命令名（fallback 路径用）。'''),
    (136, 'after', r'''权限规则解析委托共享实现。'''),
    (155, 'after', r'''精确命令建议的跳过条件：多行（换行活不过规范化）与含 * （存进去会被 hasWildcards 重解析成通配规则，转义成 \* 又是条死规则——glob 本来就不该精确自动允许）。'''),
    (194, 'after', r'''规则名也剥模块前缀，但只对 deny/ask 剥——allow 剥了会 fail-open：ModuleA\Get-Thing:* 的允许规则不能匹配 ModuleB\Get-Thing。deny/ask 过度匹配是安全的。'''),
    (215, 'after', r'''规范化命令串：别名换 canonical 名 + 分隔符归一成单空格。PowerShell 接受任意空白作分隔，而前缀规则匹配用字面空格——rm\t./x 会漏掉 Remove-Item:* 的 deny，而 acceptEdits 自动允许（用 AST cmd.name）却命中，这是一条 deny 绕过。'''),
    (333, 'after', r'''规则过滤结束。匹配三层：原始命令、canonical 命令、规则名也解析成 canonical 后互相比——deny Remove-Item 要能挡住 rm，deny rm 也要能挡住 Remove-Item。'''),
    (380, 'after', r'''一次性取齐三类规则。'''),
    (430, 'after', r'''精确匹配检查：deny → ask → allow → passthrough。'''),
    (514, 'after', r'''含前缀匹配的权限检查：deny/ask 规则优先于 allow（2a/2b 先于 3/4）。'''),
    (561, 'before', r'''解析成功路径：收集所有子命令（含控制流里的嵌套命令）。'''),
    (586, 'after', r'''isSafeOutput 判定三道闸：nameType 不是 application（scripts\Out-Null 剥名后能匹配 SAFE_OUTPUT_CMDLETS，但 PowerShell 跑的是 .ps1）+ 是安全输出 cmdlet + 零参数（Out-Null -InputObject:(1 > /etc/x) 曾以名字过滤被筛掉 → step 5 子命令为空 → 自动允许 → 括号里写文件）。'''),
    (602, 'after', r'''嵌套命令同样收集——藏在 if/for 里的命令也要查。'''),
    (624, 'after', r'''子命令收集结束。零个子命令时用整条命令兜底（fallback 元素 nameType=unknown）。'''),
    (656, 'after', r'''空命令直接允许。'''),
    (659, 'after', r'''命令只解析一次，贯穿所有子函数。'''),
    (711, 'after', r'''ask 规则不再提前返回：Get-Process; Invoke-Expression evil 在 ask(Get-Process:*)+deny(Invoke-Expression:*) 下，以前弹 ask 对话框后 deny 永不触发。现在 ask 存进 decisions[]，reduce 保证 deny 胜出。'''),
    (723, 'after', r'''UNC 检查同样延后——原始字符串检查不能在子命令 deny（step 4+）之前提前返回。'''),
    (757, 'after', r'''2c 只在「解析失败且无待定 ask」时短路：精确 allow 要能兜住 pwsh 不可用的 degraded 场景，但不能盖住 2b/UNC 的 ask。nameType 守卫防 scripts\build.exe 剥名后匹配精确 allow 而执行本地脚本。'''),
    (853, 'after', r'''解析失败路径的子命令 deny 兜底：Get-ChildItem 加一段 2000 字符填充再接 ; Invoke-Expression evil——填充让 valid=false，以前直接通用 ask、deny(iex:*) 永不触发。按 PowerShell 分隔符/分组符切片逐段过同一套规则匹配器。反引号是转义/续行不是分隔符：先折叠反引号换行、再剥剩余反引号，防 Invoke-Ex`pression 被切碎。'''),
    (874, 'after', r'''解析失败路径结束：保留 2b/UNC 的 ask 消息（decisionReason 更好），兜底扫描查不到 deny 时给通用解析错误 ask，且不建议持久化无效语法。'''),
    (898, 'after', r'''─── 收集后归约：deny > ask > allow > passthrough ───'''),
    (930, 'after', r'''安全检查（powershellCommandIsSafe）：子表达式、脚本块、编码命令、下载摇篮等一律 ask。只产生 ask/passthrough。'''),
    (955, 'after', r'''using module/assembly 与 #Requires：它们是 ScriptBlockAst 上命名块的兄弟节点而非子节点，所有命令遍历器都看不见。没有这条检查，一个 Get-Process 诱饵就能填满 subCommands 绕过空语句兜底、还被 isReadOnlyCommand 自动允许。'''),
    (971, 'after', r'''#Requires -Modules 会从 PSModulePath 触发模块加载。'''),
    (1041, 'after', r'''provider/UNC 参数扫描：env:/HKLM:/function: 访问非文件系统资源，UNC 泄 NTLM/Kerberos。反引号转义形态（`Registry`::HKLM）在 cmd.args 里已被解析器解决——先剥反引号再匹配。'''),
    (1107, 'after', r'''逐子命令 deny/ask 规则。SECURITY：同时用 AST 派生数据（name + 空格连接 args）构建 canonical 命令串再查一遍——调用运算符（& 'Remove-Item' ./x）、非空格空白（rm\t./x）、模块前缀都会让原始文本匹配漂移。'''),
    (1145, 'after', r'''cd+git 复合守卫：cd 到恶意目录让 git 变危险（假 hook、裸仓库攻击）。故意不做 cd-to-CWD 豁免——Set-Location -Path:/etc . 的首个非 dash 参数启发式会把目标猜成 . 而绕过。任何 cd 家族 cmdlet 出现即置位（bug #25：单条 Set-Location 不置位，否则压住单命令自动允许路径）。'''),
    (1166, 'after', r'''裸仓库守卫：cwd 有 HEAD/objects/refs/ 而无 .git/HEAD 时，git 把 cwd 当裸仓库并从 cwd 跑 hook。攻击者种 hooks/pre-commit、删 .git/HEAD，随后任何 git 子命令执行它。'''),
    (1234, 'after', r'''git 内部路径写守卫：复合命令先造 HEAD/hooks/refs/ 再跑 git，git 执行刚种下的恶意 hook。管道来源（"hooks/pre-commit" | New-Item -ItemType File）的路径在非 CommandAst 元素里，也要查。'''),
    (1257, 'after', r'''.git/ 写入不需要 git 子命令就危险——种下的 .git/hooks/pre-commit 在用户下次 commit 时触发。不像裸仓库检查要 gate 在 hasGitSubCommand（hooks/ 是常见项目目录名），.git/ 无歧义。'''),
    (1279, 'after', r'''路径约束（checkPathConstraints）：唯一能在归约里产出 deny 的检查。线程注入 hasCdSubCommand——复合命令含 cd 时任何路径操作都 ask，这是 CWD 去同步集群（findings #3/#21/#27/#28）的结构性修复：在路径解析层设一道闸，替代过去散落各处的 per-site 守卫。'''),
    (1316, 'after', r'''精确 allow（解析成功路径）三道闸：nameType 全子命令非 application（finding #10：canonicalCommand 把 \n 折成空格，code\n.\build.ps1 能匹配精确规则，只查 [0] 会漏第二条语句）+ 每子命令过 argLeaksValue（finding #32：用户写 PowerShell(Write-Output:*) 不是为了自动允许 Write-Output $env:ANTHROPIC_API_KEY）。'''),
    (1331, 'after', r'''只读白名单自动允许（bash 的 ls/cat/git status 等价物）。归约把它放在子命令 ask 之下（ask > allow）。'''),
    (1345, 'after', r'''文件重定向（> >> 2>）写任意路径。isReadOnlyCommand 内部已拒重定向，不会与上面的只读 allow 冲突。'''),
    (1352, 'after', r'''acceptEdits 模式处理（checkPermissionMode 只返回 allow/passthrough）。'''),
    (1368, 'after', r'''归约：deny > ask > allow。同行为第一个胜出（保住单检查场景的消息顺序）。'''),
    (1408, 'after', r'''step 5 过滤：安全输出 cmdlet 剔出审批列表（deny 已在 4.4 查过）；application 名字保留在列表里——过滤出审批列表也是一种自动允许，scripts\Set-Location . 会被静默丢掉然后执行 .ps1。Set-Location 到 cwd 的豁免用 PS_TOKENIZER_DASH_CHARS 找目标——Set-Location –Path . 的 en-dash 不能被当成位置目标。'''),
    (1432, 'after', r'''按 push 记录语句而非循环入口记录：若语句唯一子命令被用户 allow 规则 continue 掉，入口标记会让 fail-closed 闸门跳过它——if ($true) { Get-Process; $env:SECRET } 里 Get-Process 被放行、$env:SECRET 是 VariableExpressionAst 不是子命令、语句被标记见过 → 自动允许 → 秘密泄露。'''),
    (1577, 'after', r'''step 5 循环结束。每条路径都带自己的闸门：用户 allow 规则过 nameType + argLeaksValue + !hasSymlinkCreate；allowlist 捷径要求语句是可证明安全的 PipelineAst 且无 cd/符号链接；acceptEdits 委派 checkPermissionMode 单语句 AST（传 parsed.variables 让任何语句的 splatting 可见）。'''),
    (1597, 'after', r'''fail-closed 第二半：step 5 循环只遍历收集到且未被安全输出过滤的子命令。零 CommandAst 子命令的语句（裸 $env:SECRET）或唯一子命令被过滤的语句（$env:X | Out-String）从不进循环——不补这道闸它们会凭空自动允许。只补没被 push 过的语句，避免重复建议。'''),
    (1626, 'after', r'''空审批列表才自动允许，但还要过脚本块检查：Where-Object {$true} | Sort-Object {$env:PATH='evil'} 的安全输出 cmdlet 全被过滤，块内容却无人验证。hasAssignments 只查顶层（parser.ts），嵌套赋值也看不见。'''),
    (1648, 'after', r'''函数结束：有待审批子命令时收集精确命令建议（多行/含 * 的会被 suggestionForExactCommand 跳过）。'''),
]
